            "로토지파이뉴점안액 사용법은 1회 2~3방울씩, 1일 5~6회 점안하는 거예요. 이 사용법은 식약처 허가사항 그대로예요. 하루 대여섯 번이라 아침에 한 번 넣고 끝내는 인공눈물과는 사용 빈도가 좀 달라요. 정해진 용법과 용량을 지키는 게 중요하고, 넣을 때는 점안용으로만 사용해야 해요. 정량을 지키는 게 중요해요.\n\n눈에 직접 넣는 약이다 보니 오염 방지를 위해 되도록 다른 사람과 함께 쓰지 않는 게 좋아요. 소프트콘택트렌즈를 착용한 채로는 사용하면 안 되고, 하드콘택트렌즈 착용 시 불쾌감에는 쓸 수 있어요. 용액이 혼탁하거나 흐려 보이면 사용하지 말고, 30개월 이하 영아에게는 이 약을 사용하지 마세요. 손을 씻고 병 끝이 눈이나 속눈썹에 닿지 않게 넣는 습관도 중요해요. 습기와 빛을 피해 실온에 보관하고 사용기간이 지난 제품은 버리는 게 안전하죠.",
