            "제이더블유중외제약이 만든 이 점안액은 염화나트륨과 고농도 멘톨을 넣어 눈에 넣자마자 시원한 느낌이 확 퍼지는 아이스 타입이에요. 식약처 품목번호 202400824로 등록된 일반의약품이에요. 일반 인공눈물보다 청량감이 강해서 냉감을 원하는 분들이 즐겨 찾죠. 눈물 성분과 비슷한 전해질로 건조한 눈 표면을 채워주면서, 멘톨이 열감을 식혀주는 방식이에요.\n\n렌즈 착용자 사이에서 특히 인기가 많은데, 콘택트렌즈 특유의 뻑뻑함과 이물감을 청량감으로 덜어주기 때문이고요. 눈이 뜨거운 느낌이 자주 드는 여름철이나 냉방기 바람을 많이 쐬는 사무실 환경에서도 자주 찾는 편이고요. 시원해요. 다만 자극이 강하게 느껴진다면 무자극 제품으로 바꿔보는 것도 방법이에요. 같은 눈물 보조 목적이라도 시원함과 순한 정도는 제품마다 개인차가 크게 갈려서, 처음 써보는 분이라면 한 번 넣어보고 반응을 확인한 뒤 계속 쓸지 정해도 늦지 않아요.",
