            "리포직이디오점안겔은 눈이 뻑뻑하고 건조할 때 증상을 완화하려고 식약처가 허가한 일반의약품이에요. 품목번호는 201208472이고, 성분은 카보머 하나뿐이에요. 넣으면 눈물막처럼 얇은 겔 층을 만들어 수분을 붙잡아두는 방식이에요. 포인트는 층이 얇다는 거예요. 확 시원해지는 느낌은 아니에요. 겔이 각막 표면에 머무르면서 건조감을 천천히 줄여주는 쪽에 가까워요. 어디까지나 증상 완화가 목적이에요. 건조증을 일으키는 원인 자체를 없애는 약은 아니라는 점도 알아두면 좋아요.\n\n식약처 허가사항을 보면 건조성각결막염 치료는 장기간이나 지속적인 치료가 필요하다고 나와 있어요. 소아 임상시험 경험은 없다는 내용도 함께 적혀 있어요. 하루 이틀 넣어보고 판단하기보다는 안과의사와 상담하면서 꾸준히 쓰는 게 맞아요. 눈의 통증이 심하거나 예전에 안약 알레르기를 겪은 적이 있다면 임의로 시작하지 마세요. 먼저 진료부터 받으세요. 증상이 오락가락한다고 스스로 용량을 조절하기보다는 진료 후 지속 여부를 정하는 편이 안전해요.",
