            "한 번에 2~3방울씩, 하루 5~6회 넣는 게 정해진 사용법이에요. 증상에 맞춰 임의로 늘리기보다는 이 횟수를 지키는 게 중요해요. 넘치게 넣는다고 더 낫는 게 아니에요.\n\n과도하게 넣으면 오히려 충혈이 심해질 수 있다고 식약처 허가사항에도 나와 있어요. 소프트콘택트렌즈를 착용한 채로는 넣지 마세요. 렌즈 장착액으로 대신 쓰는 것도 안 돼요.\n\n용기 끝이 눈꺼풀이나 속눈썹에 닿으면 약액이 오염되거나 뿌옇게 흐려질 수 있으니 직접 닿지 않게 주의하세요. 무작정 참지 마세요. 3~4일 정도 사용해도 증상이 나아지지 않으면 사용을 멈추고 의사나 약사와 상의하는 게 맞고, 장기간 계속 사용하는 것도 권장되지 않아요.",
