            "시크린원스는 식약처 허가사항 기준으로 눈의 피로, 눈물 부족으로 인한 건조함, 콘택트렌즈 착용 시 느껴지는 불쾌감, 눈이 침침하고 눈곱이 자주 끼는 증상에 쓰는 인공눈물이에요. 하드렌즈나 소프트렌즈를 오래 착용하는 분들의 렌즈와 각막 사이가 뻑뻑해질 때 완충 역할을 해줘요. 렌즈를 장시간 끼는 직장인이나 학생이 오후로 갈수록 눈이 뻑뻑해진다고 느낄 때 특히 도움이 되는 편이에요. 식약처 품목번호 202106502로 신고된 일반의약품이에요.\n\n다만 인공눈물은 치료제가 아니에요. 눈물을 보충해 불편함을 줄여주는 제품이지, 안구 질환 자체를 없애는 약은 아니라는 뜻이에요. 눈 통증이 심하거나 충혈이 오래가면 인공눈물만 믿지 말고 안과 진료부터 받아야 해요. 렌즈를 낀 채로 화면을 오래 보는 습관이 있다면, 증상이 나타나기 전에 미리 넣어주는 것도 방법이에요.",
